import 'dart:convert';

/// A proxy [StringSink] that intercepts writes, safely escapes them for JSON,
/// and forwards the raw escaped characters to an underlying sink.
///
/// Architecturally, this class acts as a push-based streaming utility for manually
/// injecting large textual data into an active JSON serialization pipeline (such as
/// `jsonEncodeAsync`) without buffering the entire string payload in memory. It strips
/// the boundary quotes generated by standard [jsonEncode], allowing developers to
/// iteratively append escaped chunks into an open JSON string literal.
///
/// This is the push-based counterpart to `StreamingJsonString` (which provides a
/// pull-based stream ingestion pattern).
///
/// Example usage for writing a chunked JSON property:
/// ```dart
/// final buffer = StringBuffer();
/// buffer.write('{"largeText":"');
///
/// final escapingSink = JsonStringEscapingSink(buffer);
/// escapingSink.write('First chunk.\n');
/// escapingSink.write('Second chunk with "quotes".');
///
/// buffer.write('"}');
/// ```
class JsonStringEscapingSink implements StringSink {
  final StringSink _inner;

  /// Creates a [JsonStringEscapingSink] that writes escaped characters to the underlying [_inner] sink.
  ///
  /// The [_inner] sink receives the dynamically escaped output stripped of boundary
  /// quotes, allowing it to seamlessly append to an ongoing JSON serialization stream.
  const JsonStringEscapingSink(this._inner);

  /// Converts the given [object] to a string, safely escapes it for JSON embedding,
  /// and writes the resulting characters to the underlying sink.
  ///
  /// If the [object] is `null` or its string representation is empty, this operation
  /// is gracefully ignored without writing any data. The escaping logic delegates to
  /// [jsonEncode] and dynamically strips the outer quotes before appending.
  @override
  void write(Object? object) {
    final str = object?.toString();
    if (str == null || str.isEmpty) return;

    final escaped = jsonEncode(str);
    // With non-empty str, jsonEncode(str) is always >= 3 chars ("x")
    _inner.write(escaped.substring(1, escaped.length - 1));
  }

  /// Iterates over [objects] and sequentially writes their escaped string representations
  /// to the underlying sink.
  ///
  /// If a [separator] is provided, it is inserted between each object. Both the elements
  /// and the [separator] undergo the same JSON escaping process via [write]. If [objects]
  /// is empty, this method performs no action.
  @override
  void writeAll(Iterable<dynamic> objects, [String separator = ""]) {
    final iterator = objects.iterator;
    if (!iterator.moveNext()) return;

    if (separator.isEmpty) {
      do {
        write(iterator.current);
      } while (iterator.moveNext());
    } else {
      write(iterator.current);
      while (iterator.moveNext()) {
        write(separator);
        write(iterator.current);
      }
    }
  }

  /// Converts a single UTF-16 [charCode] into its string equivalent and writes its
  /// JSON-escaped representation to the underlying sink via [write].
  @override
  void writeCharCode(int charCode) {
    write(String.fromCharCode(charCode));
  }

  /// Writes the JSON-escaped string representation of [object] to the underlying sink,
  /// immediately followed by an escaped newline character (`\n`).
  ///
  /// If [object] is omitted, only the escaped newline is written.
  @override
  void writeln([Object? object = ""]) {
    write(object);
    write('\n');
  }
}
